package com.chx.claims.assignment.application;
import com.chx.claims.claim.domain.Claim; import com.chx.claims.claim.infra.ClaimRepository; import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class AssignmentService { private final ClaimRepository claims; public AssignmentService(ClaimRepository c){claims=c;} @Transactional(readOnly=true) public List<Claim> queue(){var result=claims.findAll().stream().filter(c->c.getStatus().name().equals("SUBMITTED")).toList();result.forEach(this::initialize);return result;} @Transactional(readOnly=true) public List<Claim> mine(UUID officer){var result=claims.findByAssignedOfficerId(officer);result.forEach(this::initialize);return result;} private void initialize(Claim c){c.getStatusHistory().size();c.getInfoRequests().size();} }
